from torch import Tensor, nn
import triton as triton

@triton.jit
def _l2_normalize(x: Tensor, eps: float = 1e-12) -> Tensor:
    norm = torch.sqrt(torch.sum(x * x, axis=-1, keepdims=True) + eps)
    return x / norm

# Implement the kernel_forward function
class L2NormKernel(nn.Module):
    def __init__(self, eps=1e-12):
        super(L2NormKernel, self).__init__()
        self.eps = eps

    def forward(self, x: Tensor) -> Tensor:
        return _l2_normalize(x, self.eps)

# Example usage
x = torch.randn(512, 2048)
kernel = L2NormKernel(eps=1e-12)
output = kernel(x)
print(output)
